mapper.select:
SELECT * FROM llm_analysis_results 
WHERE analysis_date BETWEEN #{startDate} AND #{endDate}
ORDER BY analysis_date ASC, created_at ASC

SELECT * FROM llm_analysis_results 
WHERE analysis_date = #{date}
ORDER BY created_at ASC

SELECT * FROM llm_analysis_results 
WHERE analysis_type = #{analysisType}
ORDER BY analysis_date DESC, created_at DESC

SELECT * FROM llm_analysis_results 
ORDER BY created_at DESC
LIMIT #{limit}
